CREATE OR REPLACE FUNCTION upsert_payment_frn_events() RETURNS TRIGGER AS $$ DECLARE v_correlation_id text; v_value numeric; BEGIN IF NEW.category <> 'frn' THEN RETURN NEW; END IF;
v_correlation_id := split_part(NEW."rowKey", '|', 1);
IF NEW.type IN ( 'uk.gov.defra.ffc.pay.payment.extracted', 'uk.gov.defra.ffc.pay.payment.enriched' ) AND NEW.data->>'value' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
v_value := (NEW.data->>'value')::numeric;
-- Convert pounds to pence for extracted events only IF NEW.type = 'uk.gov.defra.ffc.pay.payment.extracted' THEN v_value := v_value * 100; END IF;
ELSE v_value := NULL; END IF;
INSERT INTO payment_frn_events ( id, "correlationId", frn, "schemeId", "agreementNumber", "paymentRequestNumber", "originalValue", type, "lastUpdated", "providesAccountingValues" ) VALUES ( gen_random_uuid(), v_correlation_id, NEW."partitionKey", (NEW.data->>'schemeId')::int, NEW.data->>'agreementNumber', (NEW.data->>'paymentRequestNumber')::int, v_value, NEW.type, NEW."time", (NEW.data->>'providesAccountingValues')::boolean ) ON CONFLICT (frn, "correlationId") DO UPDATE SET type = CASE WHEN payment_event_rank(EXCLUDED.type) >= payment_event_rank(payment_frn_events.type) THEN EXCLUDED.type ELSE payment_frn_events.type END, "lastUpdated" = CASE WHEN payment_event_rank(EXCLUDED.type) >= payment_event_rank(payment_frn_events.type) THEN EXCLUDED."lastUpdated" ELSE payment_frn_events."lastUpdated" END, "agreementNumber" = COALESCE(EXCLUDED."agreementNumber", payment_frn_events."agreementNumber"), "originalValue" = COALESCE(payment_frn_events."originalValue", EXCLUDED."originalValue"), "providesAccountingValues" = COALESCE(EXCLUDED."providesAccountingValues", payment_frn_events."providesAccountingValues");
RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_upsert_payment_frn_events ON payments;
CREATE TRIGGER trg_upsert_payment_frn_events AFTER INSERT ON payments FOR EACH ROW EXECUTE FUNCTION upsert_payment_frn_events();

CREATE OR REPLACE FUNCTION upsert_payment_batch_events() RETURNS TRIGGER AS $$ DECLARE v_value numeric; BEGIN IF NEW.category <> 'batch' THEN RETURN NEW; END IF;
IF NEW.type IN ( 'uk.gov.defra.ffc.pay.payment.extracted', 'uk.gov.defra.ffc.pay.payment.enriched' ) AND NEW.data->>'value' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
v_value := (NEW.data->>'value')::numeric;
IF NEW.type = 'uk.gov.defra.ffc.pay.payment.extracted' THEN v_value := v_value * 100; END IF;
ELSE v_value := NULL; END IF;
INSERT INTO payment_batch_events ( id, "batchName", "schemeId", frn, "marketingYear", "agreementNumber", "paymentRequestNumber", "originalValue", type, "providesAccountingValues" ) VALUES ( gen_random_uuid(), NEW."partitionKey", (NEW.data->>'schemeId')::int, NEW.data->>'frn', (NEW.data->>'marketingYear')::int, NEW.data->>'agreementNumber', (NEW.data->>'paymentRequestNumber')::int, v_value, NEW.type, (NEW.data->>'providesAccountingValues')::boolean ) ON CONFLICT ("batchName", frn) DO UPDATE SET type = CASE WHEN payment_event_rank(EXCLUDED.type) >= payment_event_rank(payment_batch_events.type) THEN EXCLUDED.type ELSE payment_batch_events.type END, "originalValue" = COALESCE(payment_batch_events."originalValue", EXCLUDED."originalValue"), "providesAccountingValues" = COALESCE(EXCLUDED."providesAccountingValues", payment_batch_events."providesAccountingValues");
RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_upsert_payment_batch_events ON payments;
CREATE TRIGGER trg_upsert_payment_batch_events AFTER INSERT ON payments FOR EACH ROW EXECUTE FUNCTION upsert_payment_batch_events();
